package com.dailyitemgoals;

/**
 * A recurring daily target for one item.
 */
final class DailyGoal
{
	private final int itemId;
	private final String name;
	private int target;

	DailyGoal(int itemId, String name, int target)
	{
		this.itemId = itemId;
		this.name = name;
		this.target = target;
	}

	int getItemId()
	{
		return itemId;
	}

	String getName()
	{
		return name;
	}

	int getTarget()
	{
		return target;
	}

	void setTarget(int target)
	{
		this.target = target;
	}
}

package com.dailyitemgoals;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Notification;

@ConfigGroup(DailyItemGoalsConfig.GROUP)
public interface DailyItemGoalsConfig extends Config
{
	String GROUP = "dailyitemgoals";

	@ConfigItem(
		keyName = "resetTime",
		name = "Reset time",
		description = "When your daily counts go back to zero",
		position = 1
	)
	default ResetTime resetTime()
	{
		return ResetTime.LOCAL_MIDNIGHT;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Show your goals on the game screen",
		position = 2
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideCompleted",
		name = "Hide completed in overlay",
		description = "Remove goals from the overlay once they're done",
		position = 3
	)
	default boolean hideCompleted()
	{
		return false;
	}

	@ConfigItem(
		keyName = "goalNotification",
		name = "Goal complete notification",
		description = "Notify you when you reach a daily goal",
		position = 4
	)
	default Notification goalNotification()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "countAnyGain",
		name = "Count any inventory gain",
		description = "Count everything added to your inventory outside banks, shops, trades and the "
			+ "Grand Exchange. Turn on for things with no XP or used-up materials, like Blast Furnace "
			+ "bars. Ground pickups will count too.",
		position = 5
	)
	default boolean countAnyGain()
	{
		return false;
	}
}

package com.dailyitemgoals;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

class DailyItemGoalsOverlay extends OverlayPanel
{
	private static final int WIDTH = 190;

	private final DailyItemGoalsPlugin plugin;
	private final DailyItemGoalsConfig config;

	@Inject
	DailyItemGoalsOverlay(DailyItemGoalsPlugin plugin, DailyItemGoalsConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		List<GoalView> shown = new ArrayList<>();
		for (GoalView goal : plugin.getGoalViews())
		{
			if (!goal.isComplete() || !config.hideCompleted())
			{
				shown.add(goal);
			}
		}

		if (shown.isEmpty())
		{
			return null;
		}

		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
		panelComponent.getChildren().add(TitleComponent.builder().text("Daily item goals").build());
		for (GoalView goal : shown)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(goal.getName())
				.right(QuantityFormatter.formatNumber(goal.getCount()) + " / " + QuantityFormatter.formatNumber(goal.getTarget()))
				.rightColor(goal.isComplete() ? Color.GREEN : Color.WHITE)
				.build());
		}

		return super.render(graphics);
	}
}

package com.dailyitemgoals;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.ProgressBar;
import net.runelite.client.util.QuantityFormatter;

class DailyItemGoalsPanel extends PluginPanel
{
	private static final Color IN_PROGRESS = new Color(55, 120, 190);
	private static final Color COMPLETE = new Color(60, 150, 75);

	private final DailyItemGoalsPlugin plugin;
	private final ItemManager itemManager;
	private final JLabel summary = new JLabel();
	private final JButton addButton = new JButton("Add goal");
	private final JPanel list = new JPanel(new GridLayout(0, 1, 0, 6));
	private final Map<Integer, GoalRow> rows = new LinkedHashMap<>();

	DailyItemGoalsPanel(DailyItemGoalsPlugin plugin, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.itemManager = itemManager;

		setLayout(new BorderLayout(0, 8));
		list.setOpaque(false);
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JLabel title = new JLabel("Daily item goals");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		summary.setHorizontalAlignment(SwingConstants.RIGHT);
		summary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel titleRow = new JPanel(new BorderLayout());
		titleRow.setOpaque(false);
		titleRow.add(title, BorderLayout.WEST);
		titleRow.add(summary, BorderLayout.EAST);

		addButton.addActionListener(e -> plugin.promptAddGoal());

		JPanel header = new JPanel(new BorderLayout(0, 8));
		header.setOpaque(false);
		header.add(titleRow, BorderLayout.NORTH);
		header.add(addButton, BorderLayout.SOUTH);

		add(header, BorderLayout.NORTH);
		add(list, BorderLayout.CENTER);

		update(false, new ArrayList<>());
	}

	void update(boolean loggedIn, List<GoalView> goals)
	{
		addButton.setEnabled(loggedIn);

		int complete = 0;
		for (GoalView goal : goals)
		{
			complete += goal.isComplete() ? 1 : 0;
		}
		summary.setText(goals.isEmpty() ? "" : complete + " / " + goals.size() + " done");

		if (goals.isEmpty())
		{
			showMessage(loggedIn ? "Add a goal to get started." : "Log in to see your goals.");
			return;
		}

		List<Integer> ids = new ArrayList<>();
		for (GoalView goal : goals)
		{
			ids.add(goal.getItemId());
		}

		// Only rebuild when the list itself changes, so a progress update can't close an open menu.
		if (!ids.equals(new ArrayList<>(rows.keySet())))
		{
			rows.clear();
			list.removeAll();
			for (GoalView goal : goals)
			{
				GoalRow row = new GoalRow(goal);
				rows.put(goal.getItemId(), row);
				list.add(row);
			}
			list.revalidate();
			list.repaint();
		}

		for (GoalView goal : goals)
		{
			rows.get(goal.getItemId()).setGoal(goal);
		}
	}

	private void showMessage(String message)
	{
		rows.clear();
		list.removeAll();
		JLabel label = new JLabel(message);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setHorizontalAlignment(SwingConstants.CENTER);
		list.add(label);
		list.revalidate();
		list.repaint();
	}

	private class GoalRow extends JPanel
	{
		private final ProgressBar bar = new ProgressBar();

		GoalRow(GoalView goal)
		{
			int itemId = goal.getItemId();

			setLayout(new BorderLayout(6, 4));
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

			JLabel icon = new JLabel();
			icon.setPreferredSize(new Dimension(36, 32));
			itemManager.getImage(itemId).addTo(icon);

			JLabel name = new JLabel(goal.getName());
			name.setForeground(Color.WHITE);
			name.setToolTipText(goal.getName());

			bar.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
			bar.setPreferredSize(new Dimension(0, 16));

			JPanel text = new JPanel(new BorderLayout(0, 4));
			text.setOpaque(false);
			text.add(name, BorderLayout.NORTH);
			text.add(bar, BorderLayout.SOUTH);

			add(icon, BorderLayout.WEST);
			add(text, BorderLayout.CENTER);

			JPopupMenu menu = new JPopupMenu();
			menu.add(item("Edit target", () -> plugin.promptEditTarget(itemId)));
			menu.add(item("Edit today's count", () -> plugin.promptEditCount(itemId)));
			menu.add(item("Move up", () -> plugin.moveGoal(itemId, -1)));
			menu.add(item("Move down", () -> plugin.moveGoal(itemId, 1)));
			menu.add(item("Remove", () -> plugin.removeGoal(itemId)));
			setComponentPopupMenu(menu);
			icon.setInheritsPopupMenu(true);
			name.setInheritsPopupMenu(true);
			text.setInheritsPopupMenu(true);
			bar.setInheritsPopupMenu(true);
		}

		private JMenuItem item(String label, Runnable action)
		{
			JMenuItem item = new JMenuItem(label);
			item.addActionListener(e -> action.run());
			return item;
		}

		void setGoal(GoalView goal)
		{
			// Set as a percentage because the bar's own maths overflows on very large values.
			bar.setMaximumValue(100);
			bar.setValue((int) Math.min(100, goal.getCount() * 100L / goal.getTarget()));
			bar.setForeground(goal.isComplete() ? COMPLETE : IN_PROGRESS);
			bar.setLeftLabel(QuantityFormatter.formatNumber(goal.getCount()));
			bar.setRightLabel(QuantityFormatter.formatNumber(goal.getTarget()));
			bar.setCenterLabel("");
		}
	}
}

package com.dailyitemgoals;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.text.ParseException;
import java.time.Clock;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
