import net.runelite.client.game.ItemManager;
import net.runelite.client.game.chatbox.ChatboxItemSearch;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.QuantityFormatter;

@PluginDescriptor(
	name = "Daily Item Goals",
	description = "Set daily targets for items you make and track them automatically",
	tags = {"goals", "daily", "tracker", "skilling", "fletching", "smithing", "production"}
)
public class DailyItemGoalsPlugin extends Plugin
{
	private static final String GOALS_KEY = "goals";
	private static final String PROGRESS_KEY = "progress";
	private static final String UNIT_CHARS = "0123456789.kKmMbB";

	// Combat XP is left out so loot picked up straight after a kill doesn't count as made.
	private static final Set<Skill> IGNORED_SKILLS = EnumSet.of(
		Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.HITPOINTS, Skill.SLAYER);

	private static final int[] BLOCKING_INTERFACES = {
		InterfaceID.BANKMAIN,
		InterfaceID.BANK_DEPOSITBOX,
		InterfaceID.SHARED_BANK,
		InterfaceID.SHOPMAIN,
		InterfaceID.TRADEMAIN,
		InterfaceID.TRADECONFIRM,
		InterfaceID.GE_OFFERS,
		InterfaceID.GE_COLLECT,
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatboxPanelManager chatboxPanelManager;

	@Inject
	private Provider<ChatboxItemSearch> itemSearch;

	@Inject
	private Notifier notifier;

	@Inject
	private Gson gson;

	@Inject
	private DailyItemGoalsConfig config;

	@Inject
	private DailyItemGoalsOverlay overlay;

	private final ProductionDetector detector = new ProductionDetector();
	private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);
	private final Clock clock = Clock.systemDefaultZone();

	// Only touched on the client thread.
	private List<DailyGoal> goals = new ArrayList<>();
	private DailyProgress progress;

	private DailyItemGoalsPanel panel;
	private NavigationButton navButton;

	@Provides
	DailyItemGoalsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DailyItemGoalsConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new DailyItemGoalsPanel(this, itemManager);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Daily Item Goals")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);

		clientThread.invokeLater(() ->
		{
			detector.reset();
			lastXp.clear();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadState();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
		clientThread.invokeLater(() ->
		{
			goals = new ArrayList<>();
			progress = null;
		});
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		clientThread.invokeLater(this::loadState);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.LOGGING_IN)
		{
			detector.reset();
		}
		if (state == GameState.LOGIN_SCREEN)
		{
			lastXp.clear();
			goals = new ArrayList<>();
			progress = null;
			refreshPanel();
		}
		else if (state == GameState.LOGGED_IN && progress == null)
		{
			clientThread.invokeLater(this::loadState);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (DailyItemGoalsConfig.GROUP.equals(event.getGroup()) && "resetTime".equals(event.getKey()))
		{
			clientThread.invokeLater(this::rollOverIfNewDay);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		Integer previous = lastXp.put(skill, event.getXp());
		if (previous != null && event.getXp() > previous && !IGNORED_SKILLS.contains(skill))
		{
			detector.onXpGained(client.getTickCount());
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();
		if (containerId == InventoryID.WORN)
		{
			detector.onEquipmentChanged(client.getTickCount());
		}
		else if (containerId == InventoryID.INV)
		{
			detector.onInventoryChanged(snapshot(event.getItemContainer()), client.getTickCount(), isBlockingInterfaceOpen());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		rollOverIfNewDay();

		Map<Integer, Integer> made = detector.onTick(client.getTickCount(), config.countAnyGain());
		if (made.isEmpty() || progress == null)
		{
			return;
		}

		boolean changed = false;
		for (DailyGoal goal : goals)
		{
			Integer quantity = made.get(goal.getItemId());
			if (quantity == null)
			{
				continue;
			}

			int before = progress.get(goal.getItemId());
			int after = progress.add(goal.getItemId(), quantity);
			changed = true;
			if (before < goal.getTarget() && after >= goal.getTarget())
			{
				announceComplete(goal);
			}
		}

		if (changed)
		{
			saveProgress();
			refreshPanel();
		}
	}

	private Map<Integer, Integer> snapshot(ItemContainer container)
	{
		Map<Integer, Integer> items = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				items.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
		return items;
	}

	private boolean isBlockingInterfaceOpen()
	{
		for (int interfaceId : BLOCKING_INTERFACES)
		{
			Widget widget = client.getWidget(interfaceId, 0);
			if (widget != null && !widget.isHidden())
			{
				return true;
			}
		}
		return false;
	}

	private void announceComplete(DailyGoal goal)
	{
		String message = "Daily goal complete: " + QuantityFormatter.formatNumber(goal.getTarget()) + " x " + goal.getName();
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
		notifier.notify(config.goalNotification(), message);
	}

	private void rollOverIfNewDay()
	{
		if (progress != null && progress.rollTo(today()))
		{
			saveProgress();
			refreshPanel();
		}
	}

	private String today()
	{
		return config.resetTime().today(clock);
	}

	private void loadState()
	{
		goals = new ArrayList<>();
		progress = null;

		if (configManager.getRSProfileKey() != null)
		{
			List<DailyGoal> savedGoals = parse(GOALS_KEY, new TypeToken<List<DailyGoal>>()
			{
			});
			if (savedGoals != null)
			{
				goals = new ArrayList<>(savedGoals);
			}

			progress = parse(PROGRESS_KEY, new TypeToken<DailyProgress>()
			{
			});
			if (progress == null)
			{
				progress = new DailyProgress(today());
			}
			rollOverIfNewDay();
		}

		refreshPanel();
	}

	private <T> T parse(String key, TypeToken<T> type)
	{
		String json = configManager.getRSProfileConfiguration(DailyItemGoalsConfig.GROUP, key);
		if (json == null)
		{
			return null;
		}

		try
		{
			return gson.fromJson(json, type.getType());
		}
		catch (JsonSyntaxException ex)
		{
			return null;
		}
	}

	private void saveGoals()
	{
		configManager.setRSProfileConfiguration(DailyItemGoalsConfig.GROUP, GOALS_KEY, gson.toJson(goals));
	}

	private void saveProgress()
	{
		configManager.setRSProfileConfiguration(DailyItemGoalsConfig.GROUP, PROGRESS_KEY, gson.toJson(progress));
	}

	private void refreshPanel()
	{
		DailyItemGoalsPanel current = panel;
		if (current == null)
		{
			return;
		}

		boolean loggedIn = progress != null;
		List<GoalView> views = getGoalViews();
		SwingUtilities.invokeLater(() -> current.update(loggedIn, views));
	}

	/**
	 * Call on the client thread.
	 */
	List<GoalView> getGoalViews()
	{
		if (progress == null)
		{
			return Collections.emptyList();
		}

		List<GoalView> views = new ArrayList<>(goals.size());
		for (DailyGoal goal : goals)
		{
			views.add(new GoalView(goal.getItemId(), goal.getName(), progress.get(goal.getItemId()), goal.getTarget()));
		}
		return views;
	}

	void promptAddGoal()
	{
		clientThread.invokeLater(() ->
		{
			if (progress == null)
			{
				return;
			}

			Consumer<Integer> onSelected = itemId -> clientThread.invokeLater(() -> promptTargetForNewGoal(itemId));
			itemSearch.get()
				.tooltipText("Add daily goal")
				.onItemSelected(onSelected)
				.prompt("Item to track")
				.build();
		});
	}

	private void promptTargetForNewGoal(int itemId)
	{
		String name = itemManager.getItemComposition(itemId).getName();
		promptQuantity("Daily target for " + name, "", target ->
		{
			if (target <= 0)
			{
				return;
			}

			DailyGoal existing = findGoal(itemId);
			if (existing != null)
			{
				existing.setTarget(target);
			}
			else
			{
				goals.add(new DailyGoal(itemId, name, target));
			}
			saveGoals();
			refreshPanel();
		});
	}

	void promptEditTarget(int itemId)
	{
		clientThread.invokeLater(() ->
		{
			DailyGoal goal = findGoal(itemId);
			if (goal == null)
			{
				return;
			}

			promptQuantity("Daily target for " + goal.getName(), Integer.toString(goal.getTarget()), target ->
			{
				if (target > 0)
				{
					goal.setTarget(target);
					saveGoals();
					refreshPanel();
				}
			});
		});
	}

	void promptEditCount(int itemId)
	{
		clientThread.invokeLater(() ->
		{
			DailyGoal goal = findGoal(itemId);
			if (goal == null || progress == null)
			{
				return;
			}

			promptQuantity("Made today: " + goal.getName(), Integer.toString(progress.get(itemId)), count ->
			{
				progress.set(itemId, count);
				saveProgress();
				refreshPanel();
			});
		});
	}

	void moveGoal(int itemId, int offset)
	{
		clientThread.invokeLater(() ->
		{
			DailyGoal goal = findGoal(itemId);
			if (goal == null)
			{
				return;
			}

			int from = goals.indexOf(goal);
			int to = from + offset;
			if (to >= 0 && to < goals.size())
			{
				Collections.swap(goals, from, to);
				saveGoals();
				refreshPanel();
			}
		});
	}

	void removeGoal(int itemId)
	{
		clientThread.invokeLater(() ->
		{
			Iterator<DailyGoal> iterator = goals.iterator();
			while (iterator.hasNext())
			{
				if (iterator.next().getItemId() == itemId)
				{
					iterator.remove();
				}
			}

			if (progress != null)
			{
				progress.remove(itemId);
				saveProgress();
			}
			saveGoals();
			refreshPanel();
		});
	}

	private DailyGoal findGoal(int itemId)
	{
		for (DailyGoal goal : goals)
		{
			if (goal.getItemId() == itemId)
			{
				return goal;
			}
		}
		return null;
	}

	private void promptQuantity(String prompt, String value, IntConsumer onValue)
	{
		Consumer<String> onDone = text -> clientThread.invokeLater(() ->
		{
			int quantity = parseQuantity(text);
			if (quantity >= 0)
			{
				onValue.accept(quantity);
			}
		});

		chatboxPanelManager.openTextInput(prompt)
			.addCharValidator(c -> UNIT_CHARS.indexOf(c) >= 0)
			.value(value)
			.cursorAt(0, value.length())
			.onDone(onDone)
			.build();
	}

	/**
	 * @return the quantity, or -1 if the text isn't a valid amount
	 */
	static int parseQuantity(String text)
	{
		try
		{
			return (int) Math.min(QuantityFormatter.parseQuantity(text), Integer.MAX_VALUE);
		}
		catch (ParseException ex)
		{
			return -1;
		}
	}
}

package com.dailyitemgoals;

import java.util.HashMap;
import java.util.Map;

/**
 * How many of each item have been made on one day. Counts clear when the day changes.
 */
final class DailyProgress
{
	private String day;
	private Map<Integer, Integer> counts = new HashMap<>();

	DailyProgress(String day)
	{
		this.day = day;
	}

	/**
	 * Moves to the given day, clearing the counts if it's a different day.
	 *
	 * @return true if the counts were cleared
	 */
	boolean rollTo(String today)
	{
		if (today.equals(day))
		{
			return false;
		}

		day = today;
		counts = new HashMap<>();
		return true;
	}

	int get(int itemId)
	{
		return counts.getOrDefault(itemId, 0);
	}

	/**
	 * @return the new count, capped at Integer.MAX_VALUE
	 */
	int add(int itemId, int quantity)
	{
		long total = (long) get(itemId) + quantity;
		int capped = (int) Math.min(total, Integer.MAX_VALUE);
		counts.put(itemId, capped);
		return capped;
	}

	void set(int itemId, int count)
	{
		counts.put(itemId, count);
	}

	void remove(int itemId)
	{
		counts.remove(itemId);
	}
}

