package com.dailyitemgoals;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

/**
 * Works out which inventory gains are items the player made, rather than items they moved
 * around. A gain counts if it happened outside a bank, shop, trade or Grand Exchange screen
 * and either XP was gained around the same time, or something else in the inventory was used
 * up in the same change (for making things that give no XP, such as unfinished potions).
 *
 * XP and inventory updates can land on neighbouring ticks in either order, so a gain is held
 * for two ticks before it's decided.
 */
final class ProductionDetector
{
	private static final int WINDOW_TICKS = 1;
	private static final int DECISION_DELAY_TICKS = WINDOW_TICKS + 1;

	private static final class PendingGain
	{
		private final int tick;
		private final int itemId;
		private final int quantity;
		private final boolean consumedMaterial;

		private PendingGain(int tick, int itemId, int quantity, boolean consumedMaterial)
		{
			this.tick = tick;
			this.itemId = itemId;
			this.quantity = quantity;
			this.consumedMaterial = consumedMaterial;
		}
	}

	private final Deque<PendingGain> pending = new ArrayDeque<>();
	private final Deque<Integer> xpTicks = new ArrayDeque<>();
	private final Deque<Integer> equipmentTicks = new ArrayDeque<>();
	private Map<Integer, Integer> lastInventory;

	/**
	 * Forgets everything, so the next inventory seen becomes the new baseline.
	 */
	void reset()
	{
		pending.clear();
		xpTicks.clear();
		equipmentTicks.clear();
		lastInventory = null;
	}

	/**
	 * @param inventory item ID to total quantity, with noted items already merged into unnoted
	 * @param blocked   true if a bank, shop, trade or Grand Exchange screen is open
	 */
	void onInventoryChanged(Map<Integer, Integer> inventory, int tick, boolean blocked)
	{
		Map<Integer, Integer> previous = lastInventory;
		lastInventory = new HashMap<>(inventory);

		if (previous == null || blocked)
		{
			return;
		}

		List<Integer> gainedItems = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : inventory.entrySet())
		{
			if (entry.getValue() > previous.getOrDefault(entry.getKey(), 0))
			{
				gainedItems.add(entry.getKey());
			}
		}

		for (int itemId : gainedItems)
		{
			int quantity = inventory.get(itemId) - previous.getOrDefault(itemId, 0);
			pending.add(new PendingGain(tick, itemId, quantity, lostAnotherItem(previous, inventory)));
		}
	}

	private static boolean lostAnotherItem(Map<Integer, Integer> previous, Map<Integer, Integer> current)
	{
		for (Map.Entry<Integer, Integer> entry : previous.entrySet())
		{
			if (current.getOrDefault(entry.getKey(), 0) < entry.getValue())
			{
				return true;
			}
		}
		return false;
	}

	void onXpGained(int tick)
	{
		xpTicks.add(tick);
	}

	void onEquipmentChanged(int tick)
	{
		equipmentTicks.add(tick);
	}

	/**
	 * Decides any gains that have waited long enough.
	 *
	 * @param countAnyGain true to count every gain outside blocked screens
	 * @return item ID to quantity made
	 */
	Map<Integer, Integer> onTick(int tick, boolean countAnyGain)
	{
		Map<Integer, Integer> made = new HashMap<>();

		Iterator<PendingGain> gains = pending.iterator();
		while (gains.hasNext())
		{
			PendingGain gain = gains.next();
			if (tick - gain.tick < DECISION_DELAY_TICKS)
			{
				break;
			}

			gains.remove();
			if (countAnyGain || isProduction(gain))
			{
				made.merge(gain.itemId, gain.quantity, Integer::sum);
			}
		}

		prune(xpTicks, tick);
		prune(equipmentTicks, tick);
		return made;
	}

	private boolean isProduction(PendingGain gain)
	{
		if (nearby(xpTicks, gain.tick))
		{
			return true;
		}

		// Swapping gear also takes one item out of the inventory and puts another in.
		return gain.consumedMaterial && !nearby(equipmentTicks, gain.tick);
	}

	private static boolean nearby(Deque<Integer> ticks, int tick)
	{
		for (int candidate : ticks)
		{
			if (Math.abs(candidate - tick) <= WINDOW_TICKS)
			{
				return true;
			}
		}
		return false;
	}

	private static void prune(Deque<Integer> ticks, int tick)
	{
		int keepFrom = tick - DECISION_DELAY_TICKS - WINDOW_TICKS;
		while (!ticks.isEmpty() && ticks.peekFirst() < keepFrom)
		{
			ticks.removeFirst();
		}
	}
}

package com.dailyitemgoals;

import java.time.Clock;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;

public enum ResetTime
{
	LOCAL_MIDNIGHT("Local midnight", ZoneId.systemDefault()),
	GAME_RESET("Game reset (00:00 UTC)", ZoneOffset.UTC);

	private final String label;
	private final ZoneId zone;

	ResetTime(String label, ZoneId zone)
	{
		this.label = label;
		this.zone = zone;
	}

	String today(Clock clock)
	{
		return LocalDate.now(clock.withZone(zone)).toString();
	}

	@Override
	public String toString()
	{
		return label;
	}
}

