package com.dailyitemgoals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.Test;

public class DailyProgressTest
{
	@Test
	public void countsClearWhenTheDayChanges()
	{
		DailyProgress progress = new DailyProgress("2026-11-05");
		progress.add(859, 400);
		assertFalse(progress.rollTo("2026-11-05"));
		assertEquals(400, progress.get(859));
		assertTrue(progress.rollTo("2026-11-06"));
		assertEquals(0, progress.get(859));
	}

	@Test
	public void addCapsInsteadOfOverflowing()
	{
		DailyProgress progress = new DailyProgress("2026-11-05");
		progress.set(1, Integer.MAX_VALUE);
		assertEquals(Integer.MAX_VALUE, progress.add(1, 5));
	}

	@Test
	public void survivesSavingAndLoading()
	{
		Gson gson = new Gson();
		DailyProgress progress = new DailyProgress("2026-11-05");
		progress.add(859, 400);

		DailyProgress loaded = gson.fromJson(gson.toJson(progress), DailyProgress.class);
		assertEquals(400, loaded.get(859));
		assertFalse(loaded.rollTo("2026-11-05"));

		DailyGoal goal = gson.fromJson(gson.toJson(new DailyGoal(859, "Magic longbow", 1000)), DailyGoal.class);
		assertEquals(859, goal.getItemId());
		assertEquals("Magic longbow", goal.getName());
		assertEquals(1000, goal.getTarget());
	}

	@Test
	public void gameResetUsesUtcDate()
	{
		Clock lateUtc = Clock.fixed(Instant.parse("2026-07-01T23:30:00Z"), ZoneOffset.ofHours(1));
		assertEquals("2026-07-01", ResetTime.GAME_RESET.today(lateUtc));
	}

	@Test
	public void quantityShorthandParses()
	{
		assertEquals(1000, DailyItemGoalsPlugin.parseQuantity("1000"));
		assertEquals(1000, DailyItemGoalsPlugin.parseQuantity("1k"));
		assertEquals(1500000, DailyItemGoalsPlugin.parseQuantity("1.5m"));
		assertEquals(-1, DailyItemGoalsPlugin.parseQuantity("k"));
	}
}

package com.dailyitemgoals;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

public class ProductionDetectorTest
{
	private static final int BOW = 859;
	private static final int UNSTRUNG = 70;
	private static final int STRING = 1777;
	private static final int TIPS = 823;
	private static final int BAR = 2361;

	private ProductionDetector detector;

	@Before
	public void setUp()
	{
		detector = new ProductionDetector();
	}

	private static Map<Integer, Integer> inv(int... idThenQuantity)
	{
		Map<Integer, Integer> items = new HashMap<>();
		for (int i = 0; i < idThenQuantity.length; i += 2)
		{
			items.put(idThenQuantity[i], idThenQuantity[i + 1]);
		}
		return items;
	}

	private int made(int item, int throughTick)
	{
		int total = 0;
		for (int tick = 0; tick <= throughTick; tick++)
		{
			total += detector.onTick(tick, false).getOrDefault(item, 0);
		}
		return total;
	}

	@Test
	public void fletchingWithXpCounts()
	{
		detector.onInventoryChanged(inv(UNSTRUNG, 14, STRING, 14), 1, false);
		detector.onInventoryChanged(inv(UNSTRUNG, 13, STRING, 13, BOW, 1), 3, false);
		detector.onXpGained(3);
		detector.onInventoryChanged(inv(UNSTRUNG, 12, STRING, 12, BOW, 2), 5, false);
		detector.onXpGained(5);
		assertEquals(2, made(BOW, 10));
	}

	@Test
	public void stackableGainCountsTheDifference()
	{
		detector.onInventoryChanged(inv(BAR, 5, TIPS, 100), 1, false);
		detector.onInventoryChanged(inv(BAR, 4, TIPS, 110), 3, false);
		detector.onXpGained(3);
		assertEquals(10, made(TIPS, 8));
	}

	@Test
	public void xpArrivingOnTheTickBeforeOrAfterStillCounts()
	{
		detector.onInventoryChanged(inv(), 1, false);
		detector.onXpGained(3);
		detector.onInventoryChanged(inv(TIPS, 10), 4, false);
		assertEquals(10, made(TIPS, 8));

		setUp();
		detector.onInventoryChanged(inv(), 1, false);
		detector.onInventoryChanged(inv(TIPS, 10), 4, false);
		for (int tick = 0; tick <= 4; tick++)
		{
			assertTrue(detector.onTick(tick, false).isEmpty());
		}
		detector.onXpGained(5);
		assertTrue(detector.onTick(5, false).isEmpty());
		assertEquals(10, (int) detector.onTick(6, false).get(TIPS));
	}

	@Test
	public void xpTooFarAwayDoesNotCount()
	{
		detector.onInventoryChanged(inv(), 1, false);
		detector.onXpGained(1);
		detector.onInventoryChanged(inv(TIPS, 10), 5, false);
		detector.onXpGained(9);
		assertEquals(0, made(TIPS, 12));
	}

	@Test
	public void bankWithdrawalDoesNotCountEvenWithXpNearby()
	{
		detector.onInventoryChanged(inv(), 1, false);
		detector.onXpGained(3);
		detector.onInventoryChanged(inv(BOW, 28), 3, true);
		assertEquals(0, made(BOW, 8));
	}

	@Test
	public void gainAfterTheBankClosesComparesAgainstWhatWasWithdrawn()
	{
		detector.onInventoryChanged(inv(), 1, false);
		detector.onInventoryChanged(inv(BOW, 5), 2, true);
		detector.onInventoryChanged(inv(BOW, 6), 4, false);
		detector.onXpGained(4);
		assertEquals(1, made(BOW, 9));
	}

	@Test
	public void groundPickupDoesNotCount()
	{
		detector.onInventoryChanged(inv(), 1, false);
		detector.onInventoryChanged(inv(BOW, 1), 3, false);
		assertEquals(0, made(BOW, 8));
	}

	@Test
	public void madeWithNoXpCountsWhenMaterialsAreUsed()
	{
		int unf = 91;
		int herb = 257;
		detector.onInventoryChanged(inv(herb, 14), 1, false);
		detector.onInventoryChanged(inv(herb, 13, unf, 1), 3, false);
		assertEquals(1, made(unf, 8));
	}

	@Test
	public void gearSwapDoesNotCount()
	{
		int sword = 1333;
		int axe = 1359;
		detector.onInventoryChanged(inv(sword, 1), 1, false);
		detector.onInventoryChanged(inv(axe, 1), 3, false);
		detector.onEquipmentChanged(3);
		assertEquals(0, made(axe, 8));
	}

	@Test
	public void firstInventorySeenIsTheBaseline()
	{
		detector.onXpGained(1);
		detector.onInventoryChanged(inv(BOW, 28), 1, false);
		assertEquals(0, made(BOW, 6));
	}

	@Test
	public void resetClearsTheBaselineAndPendingGains()
	{
		detector.onInventoryChanged(inv(), 1, false);
		detector.onInventoryChanged(inv(BOW, 1), 2, false);
		detector.onXpGained(2);
		detector.reset();
		detector.onInventoryChanged(inv(BOW, 28), 3, false);
		assertEquals(0, made(BOW, 8));
	}

	@Test
	public void countAnyGainIncludesPickupsButNotBlockedScreens()
	{
		detector.onInventoryChanged(inv(), 1, false);
		detector.onInventoryChanged(inv(BOW, 1), 2, false);
		detector.onInventoryChanged(inv(BOW, 5), 3, true);
		assertEquals(Collections.singletonMap(BOW, 1), detector.onTick(10, true));
	}
}
